```json
{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, metric, value FROM abnormal_metrics WHERE metric IN ('k8s.container.ready','k8s.container.restarts') AND attr_k8s_pod_name LIKE 'user-%' ORDER BY time",
          "claim": "The user pod's container stays not-ready from 12:50:05 to the end while its restart count climbs from 2 to 6."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, quantile_cont(duration,0.5)/1e3 AS p50_us FROM abnormal_traces WHERE service_name='frontend' AND span_name='user.User/CheckUser' GROUP BY 1",
          "claim": "Frontend's user.User/CheckUser calls fail 355 of 356 times, returning in about 14 µs, consistent with refused connections to a down pod."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) AS n FROM abnormal_traces WHERE service_name='user' GROUP BY 1",
          "claim": "The user service emits only one span in the abnormal window, versus about 58 spans per minute normally."
        }
      ]
    },
    {
      "service": "attractions",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, value FROM abnormal_metrics WHERE metric='container.cpu.usage' AND attr_k8s_pod_name LIKE 'attractions-%' ORDER BY time LIMIT 25",
          "claim": "The attractions container CPU jumps from 0.002 to about 2.8 cores by 12:50:15 and pins near 3.76 cores."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, avg(value) AS avg_cpu, max(value) AS max_cpu FROM abnormal_metrics WHERE metric='container.cpu.usage' AND attr_k8s_pod_name LIKE 'attractions-%' UNION ALL SELECT 'nor', avg(value), max(value) FROM normal_metrics WHERE metric='container.cpu.usage' AND attr_k8s_pod_name LIKE 'attractions-%'",
          "claim": "Attractions container CPU averages 3.65 cores abnormally versus 0.002 cores in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n FROM abnormal_traces WHERE service_name='attractions' GROUP BY 1,2",
          "claim": "Attractions emits only one span during the abnormal window, while its pod stays running and ready with no restarts."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants','HTTP /user') GROUP BY 1",
          "claim": "User-facing frontend routes /cinema, /museums, /restaurants and /user fail on almost every request in the abnormal window."
        }
      ]
    },
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n FROM abnormal_traces WHERE span_name LIKE 'attractions.Attractions/%' GROUP BY 1,2",
          "claim": "Frontend's attractions calls (NearbyCinema, NearbyMus, NearbyRest) nearly vanish in the abnormal window, leaving the attraction routes failing."
        }
      ]
    }
  ]
}
```

